#include <bits/stdc++.h>
#define err(args...) {}
#ifdef DEBUG
#include "_debug.cpp"
#include "callable.hpp/callable.hpp"
#endif
#define endl '\n'
using namespace std;
using ll = long long;
const int N = 10;
string grid[N];
int scientists[N][N] = {};
int rescue[N][N] = {};
int infection_time[N][N] = {};
int delta_i[] = {-1, 1, 0, 0};
int delta_j[] = {0, 0, -1, 1};
int reach[N][N][N][N] = {};
const int MAX_FLOW = 2 * N * N + 2;
const int INF = 1'000'000'000;
vector<int> adj_list[MAX_FLOW+1];
int capacity[MAX_FLOW][MAX_FLOW], flow[MAX_FLOW][MAX_FLOW], ptr[MAX_FLOW], dist[MAX_FLOW], parent[MAX_FLOW];

bool build_level_graph(int s, int t) {
    memset(dist, -1, sizeof dist);
    dist[s] = 0;
    queue<int> q;
    q.push(s);
    while(!q.empty()) {
        int u = q.front(); q.pop();
        for(auto v : adj_list[u]) {
            if(capacity[u][v] - flow[u][v] > 0 && dist[v] == -1) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
    return dist[t] != -1;
}

bool dfs_augment(int u, int t) {
    if(u == t) return true;
    for(int& i = ptr[u]; i < (int)adj_list[u].size(); i++) {
        int v = adj_list[u][i];
        if(dist[v] == dist[u] + 1 && capacity[u][v] - flow[u][v] > 0 && dfs_augment(v, t)) {
            parent[v] = u;
            return true;
        }
    }
    return false;
}

bool find_path(int s, int t) {
    memset(parent, -1, sizeof parent);
    parent[s] = 0;
    return dfs_augment(s, t);
}

void init_network() {
    memset(capacity, 0, sizeof capacity);
    memset(flow, 0, sizeof flow);
}

void add_network_edge(int u, int v, int cap) {
    adj_list[u].push_back(v);
    adj_list[v].push_back(u);
    capacity[u][v] += cap;
}

int max_network_flow(int s, int t) {
    int total = 0;
    while(build_level_graph(s, t)) {
        memset(ptr, 0, sizeof ptr);
        while(find_path(s, t)) {
            int push_flow = INF;
            for(int v = t, u = parent[v]; v != s; v = u, u = parent[v]) {
                push_flow = min(push_flow, capacity[u][v] - flow[u][v]);
            }
            for(int v = t, u = parent[v]; v != s; v = u, u = parent[v]) {
                flow[u][v] += push_flow;
                flow[v][u] -= push_flow;
            }
            total += push_flow;
        }
    }
    return total;
}

int node_index(int n, int i, int j, bool right_side) {
    return i * n + j + (right_side ? n * n : 0);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, t;
    cin >> n >> t;
    string line;
    pair<int,int> explosion_point;
    for(int i=0; i<n; i++) {
        cin >> line;
        for(int j=0; j<n; j++) {
            if(line[j] == 'Y') {
                grid[i][j] = 'Y';
            } else if(line[j] == 'Z') {
                grid[i][j] = 'Z';
                explosion_point = {i,j};
            } else {
                grid[i][j] = '.';
                scientists[i][j] += line[j] - '0';
            }
        }
    }
    for(int i=0; i<n; i++) {
        cin >> line;
        for(int j=0; j<n; j++) {
            if(line[j] != 'Y' && line[j] != 'Z') {
                rescue[i][j] += line[j] - '0';
            }
        }
    }
    memset(infection_time, -1, sizeof infection_time);
    infection_time[explosion_point.first][explosion_point.second] = 0;
    queue<pair<int,int>> q;
    q.push(explosion_point);
    while(!q.empty()) {
        int i = q.front().first, j = q.front().second;
        q.pop();
        for(int d=0; d<4; d++) {
            int ni = i + delta_i[d], nj = j + delta_j[d];
            if(0 <= ni && ni < n && 0 <= nj && nj < n && grid[ni][nj] == '.' && infection_time[ni][nj] == -1) {
                infection_time[ni][nj] = infection_time[i][j] + 1;
                q.push({ni, nj});
            }
        }
    }
    memset(reach, -1, sizeof reach);
    for(int i=0; i<n; i++) {
        for(int j=0; j<n; j++) {
            if(grid[i][j] == '.') {
                reach[i][j][i][j] = 0;
                queue<pair<int,int>> q2;
                q2.push({i,j});
                while(!q2.empty()) {
                    int ii = q2.front().first, jj = q2.front().second;
                    q2.pop();
                    if(infection_time[ii][jj] == -1 || reach[i][j][ii][jj] < infection_time[ii][jj]) {
                        for(int d=0; d<4; d++) {
                            int ni = ii + delta_i[d], nj = jj + delta_j[d];
                            if(0 <= ni && ni < n && 0 <= nj && nj < n && grid[ni][nj] == '.' &&
                               (infection_time[ni][nj] == -1 || reach[i][j][ii][jj] + 1 <= infection_time[ni][nj]) &&
                               reach[i][j][ni][nj] == -1) {
                                reach[i][j][ni][nj] = reach[i][j][ii][jj] + 1;
                                q2.push({ni, nj});
                            }
                        }
                    }
                }
            }
        }
    }
    int source = 2 * n * n, sink = 2 * n * n + 1;
    init_network();
    for(int i=0; i<n; i++) {
        for(int j=0; j<n; j++) {
            if(scientists[i][j]) {
                add_network_edge(source, node_index(n, i, j, false), scientists[i][j]);
            }
            if(rescue[i][j]) {
                add_network_edge(node_index(n, i, j, true), sink, rescue[i][j]);
            }
            for(int ii=0; ii<n; ii++) {
                for(int jj=0; jj<n; jj++) {
                    if(0 <= reach[i][j][ii][jj] && reach[i][j][ii][jj] <= t) {
                        add_network_edge(node_index(n, i, j, false), node_index(n, ii, jj, true), INF);
                    }
                }
            }
        }
    }
    cout << max_network_flow(source, sink) << endl;
    return 0;
}
